// brain_health.test.ts — the pure core behind `amico brain-health` (amicode
// #1687, brain flywheel slice 8 — the brain measures itself): the receipt
// parser over the notturno journal's own bytes, the five KPI families computed
// over fixture receipts + fixture claim state, and the dated brief render.
//
// FIXTURE DISCIPLINE (the issue's Testing Decision — "fixture receipts +
// fixture claims → pinned KPI assertions"): every fixture is generated by the
// machinery that owns its format — the receipts journal through the real
// notturno_passes writer, the candidate notes through the real distill
// renderer, the review queue through the real lifecycle renderer — so the
// parser can never drift from the writers, and the pinned numbers below are
// the report's contract.
//
// The report MEASURES, never acts: no fixture substrate is ever written by
// the core, and every number carries the provenance line that produced it.
//
// Run: `pnpm --filter @amicode/amico-run test brain_health`
import { describe, it, expect } from "vitest";
import { mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { stringify as stringifyYaml } from "yaml";

import { appendSection, renderPass } from "../src/notturno_passes.js";
import { renderClaimNote as renderCandidateNote } from "../src/distill.js";
import { loadRegistryClaims } from "../src/claims.js";
import { renderQueueFile, type QueueEntry } from "../src/lifecycle.js";
import { writeDistillState, stampDistilled, type DistillState } from "../src/distill.js";
import {
  BRAIN_HEALTH_JOB,
  parsePasses,
  loadCandidateStamps,
  readReviewQueueCount,
  computeHealthReport,
  renderHealthBrief,
} from "../src/brain_health.js";

const PERIOD = "2026-10";
const CLOCK = () => new Date("2026-10-31T00:00:00.000Z");

// ── the fixture journal: 13 receipts, generated by the single writer ───────────

/** One receipt row, written through the real renderPass. */
function receipt(date: string, job: string, outcome: string, status = "ok"): string {
  return renderPass({ job, status, outcome, duration_s: 12, artifacts: [], when: new Date(`${date}T04:00:00.000Z`) });
}

function fixtureJournal(): string {
  const dir = mkdtempSync(join(tmpdir(), "brain-health-journal-"));
  const lines: string[] = [
    // September history (outside the period — the report windows on period)
    receipt(
      "2026-09-28",
      "distill",
      "distill: scanned 12 sessions (substantive 4, junk 8), distilled 4, claims 3, none 1, errors 0",
    ),
    receipt("2026-09-30", "prune", "prune: 1 fixes applied (1 unambiguous findings), 2 drift findings flagged for a human"),
    receipt(
      "2026-09-30",
      BRAIN_HEALTH_JOB,
      "brain-health: period 2026-09 — receipts 4, claims 3, created 3, applied 1, refuted 0, drift 2 — brief briefs/health-2026-09.md",
    ),
    // the period under test
    receipt("2026-10-01", "distill", "distill: scanned 30 sessions (substantive 10, junk 20), distilled 8, claims 6, none 2, errors 0"),
    receipt("2026-10-02", "distill", "distill: scanned 32 sessions (substantive 11, junk 21), distilled 3, claims 2, none 1, errors 0"),
    receipt("2026-10-07", "prune", "prune: 2 fixes applied (2 unambiguous findings), 1 drift findings flagged for a human"),
    receipt("2026-10-14", "prune", "prune: 0 fixes applied (0 unambiguous findings), 4 drift findings flagged for a human"),
    receipt(
      "2026-10-06",
      "promote",
      "promote: 3 claims proposed (bundle promote-20261006-060000), overflow 1 carried, excluded 0 — PROPOSES only, a human merges",
    ),
    receipt("2026-10-08", "synthesize", "synthesize: 2 hopper proposals, 1 already proposed (skipped), 1 patterns carried — strategy untouched"),
    receipt(
      "2026-10-05",
      "extract-meetings",
      "extract-meetings: proposed tags for meeting-2026-10-05.md (products 2, projects 1, entities 3, types 1, themes 2), 1 named gaps, proposed 2 hopper item(s)",
    ),
    receipt("2026-10-12", "extract-meetings", "extract-meetings: skipped meeting-2026-10-12.md (status tagged)"),
    receipt("2026-10-09", "triage-papers", "triage-papers: scanned 12 papers (high 3), seeded 2, no-match 4, skipped 6"),
    // a status-OK distill whose outcome left the writer's pinned shape → a named finding (writer drift)
    receipt("2026-10-03", "distill", "distill: crashed mid-pass"),
    // a FAILED pass: counted in the receipts meta (failure is a fact), excluded from every family, never a finding
    receipt("2026-10-04", "distill", "distill: jev middle layer disabled — fail-open, nothing distilled", "failed"),
  ];
  for (const section of lines) appendSection(dir, section);
  return readFileSync(join(dir, "scheduled-passes.md"), "utf8");
}

// ── the fixture registry: 5 claims with pinned history events ────────────────

function claimNote(file: string, claim: Record<string, unknown>, dir: string): void {
  writeFileSync(join(dir, file), `---\n${stringifyYaml(claim, { lineWidth: 0 }).trimEnd()}\n---\n\n# ${claim.statement}\n\nfixture claim (brain_health.test.ts).\n`);
}

