// ── the fixture candidate area: 3 candidate notes through the real renderer ──

function fixtureCandidates(): string {
  const dir = mkdtempSync(join(tmpdir(), "brain-health-candidates-"));
  const note = (sessionId: string, updatedMs: number, distilledAt: string): string =>
    renderCandidateNote({
      sessionId,
      sessionTitle: `session ${sessionId}`,
      sessionCreatedMs: updatedMs - 86_400_000,
      sessionUpdatedMs: updatedMs,
      sourceDb: "/fixture/chat.db",
      distilledAt,
      claimType: "insight",
      confidence: 0.9,
      evidence: [{ messageId: `msg-${sessionId}`, role: "user", timeCreatedMs: updatedMs, text: "fixture evidence" }],
    });
  writeFileSync(join(dir, "claim-sess-a.md"), note("sess-a", Date.parse("2026-09-25T00:00:00.000Z"), "2026-10-01T00:00:00.000Z"));
  writeFileSync(join(dir, "claim-sess-b.md"), note("sess-b", Date.parse("2026-10-01T12:00:00.000Z"), "2026-10-02T00:00:00.000Z"));
  writeFileSync(join(dir, "claim-sess-c.md"), note("sess-c", Date.parse("2026-09-20T00:00:00.000Z"), "2026-09-28T00:00:00.000Z"));
  return dir;
}

/** The fixture review queue — rendered by the real lifecycle renderer, two entries. */
function fixtureQueue(): string {
  const path = join(mkdtempSync(join(tmpdir(), "brain-health-queue-")), "review-queue.md");
  const entry = (file: string, days: number): QueueEntry => ({
    file,
    statement: `stale claim ${file}`,
    type: "insight",
    status: "unverified",
    confidence: "low",
    applied: 0,
    last_applied: null,
    age_days: days,
    reason: `never applied — no lifecycle activity since long ago, ${days} days beyond the 90-day window`,
  });
  writeFileSync(
    path,
    renderQueueFile([entry("insight-old-a.md", 120), entry("insight-old-b.md", 150)], { now: CLOCK(), windowDays: 90 }),
  );
  return path;
}

/** The fixture distill state stamp: 9 sessions ever distilled. */
function fixtureDistillState(): number {
  let state: DistillState = { schema_version: 1, entries: {} };
  for (let i = 0; i < 9; i++) state = stampDistilled(state, `sess-${i}`, "insight", null, "2026-10-02T04:00:00.000Z");
  const path = join(mkdtempSync(join(tmpdir(), "brain-health-state-")), "distill-state.json");
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, JSON.stringify(state));
  return 9;
}

// ── parsePasses: the journal's own bytes, via the single writer ───────────────

describe("parsePasses — the notturno journal, read by its writer's shape", () => {
  it("parses every fixture section: date, job, status, outcome, duration", () => {
    const { receipts, findings } = parsePasses(fixtureJournal());
    expect(receipts.length).toBe(14);
    expect(findings).toEqual([]);
    const first = receipts.find((r) => r.date === "2026-10-01")!;
    expect(first.job).toBe("distill");
    expect(first.status).toBe("ok");
    expect(first.outcome).toBe("distill: scanned 30 sessions (substantive 10, junk 20), distilled 8, claims 6, none 2, errors 0");
    expect(first.duration_s).toBe(12);
    const failed = receipts.find((r) => r.date === "2026-10-04")!;
    expect(failed.status).toBe("failed");
  });

  it("parses a header-only journal as empty (no sections, no findings)", () => {
    const { receipts, findings } = parsePasses("# Scheduled passes\n\nOne record per pass. Nothing here yet.\n");
    expect(receipts.length).toBe(0);
    expect(findings).toEqual([]);
  });

  it("names a malformed section header, never silently drops it", () => {
    const { receipts, findings } = parsePasses("## Pass not-a-date — distill — ok\n\n- distill: scanned 1 sessions (substantive 1, junk 0), distilled 1, claims 0, none 1, errors 0\n");
    expect(receipts.length).toBe(0);
    expect(findings.length).toBe(1);
    expect(findings[0]).toContain("not-a-date");
  });
});

// ── the loaders (candidate stamps, review queue) ──────────────────────────────

describe("the state loaders", () => {
  it("loads candidate stamps: session_id, session_updated, distilled_at", () => {
    const { stamps, skipped } = loadCandidateStamps(fixtureCandidates());
    expect(skipped).toEqual([]);
    expect(stamps.length).toBe(3);
    const a = stamps.find((s) => s.session_id === "sess-a")!;
    expect(a.file).toBe("claim-sess-a.md");
    expect(a.session_updated).toBe("2026-09-25T00:00:00.000Z");
    expect(a.distilled_at).toBe("2026-10-01T00:00:00.000Z");
  });

  it("names a non-conforming candidate note, never guesses a stamp", () => {
    const dir = mkdtempSync(join(tmpdir(), "brain-health-badcand-"));
    writeFileSync(join(dir, "not-a-candidate.md"), "---\ntype: note\n---\n\nno distill fields\n");
    const { stamps, skipped } = loadCandidateStamps(dir);
    expect(stamps.length).toBe(0);
    expect(skipped.length).toBe(1);
    expect(skipped[0]).toContain("not-a-candidate.md");
  });

  it("reads the review queue's own rendered count", () => {
    const { count, finding } = readReviewQueueCount(fixtureQueue());
    expect(count).toBe(2);
    expect(finding).toBeUndefined();
  });

  it("reads an empty queue as 0; a missing queue is null, never a guess", () => {
    const emptyPath = join(mkdtempSync(join(tmpdir(), "brain-health-emptyq-")), "review-queue.md");
    writeFileSync(emptyPath, renderQueueFile([], { now: CLOCK(), windowDays: 90 }));
    expect(readReviewQueueCount(emptyPath).count).toBe(0);
    const missing = readReviewQueueCount(join(mkdtempSync(join(tmpdir(), "brain-health-noq-")), "review-queue.md"));
    expect(missing.count).toBeNull();
  });
});

// ── the five KPI families over the fixture period — the pinned contract ──────

function fixtureReport() {
  const registryDir = fixtureRegistry();
  const { claims } = loadRegistryClaims(registryDir);
  const { receipts } = parsePasses(fixtureJournal());
  const { stamps } = loadCandidateStamps(fixtureCandidates());
  return computeHealthReport({
    period: PERIOD,
    receipts,
    claims,
    candidates: stamps,
    review_queue: readReviewQueueCount(fixtureQueue()).count,
    pending_tag: 2,
    distill_stamped: fixtureDistillState(),
  });
}

describe("computeHealthReport — fixture-pinned KPIs over 2026-10", () => {
  const report = fixtureReport();

  it("receipts meta: 14 total, 11 in period (failed passes included), per-job counts", () => {
    expect(report.receipts.total).toBe(14);
    expect(report.receipts.in_period).toBe(11);
    expect(report.receipts.by_job).toEqual({
      distill: 4,
      prune: 2,
      promote: 1,
      synthesize: 1,
      "extract-meetings": 2,
      "triage-papers": 1,
    });
  });

  it("family 1 — created 8 (receipts) vs applied 3 (claim history), ratio 0.375", () => {
    expect(report.created_vs_applied.created).toBe(8);
    expect(report.created_vs_applied.created_provenance).toEqual(["2026-10-01: claims 6", "2026-10-02: claims 2"]);
    expect(report.created_vs_applied.applied).toBe(3);
    expect(report.created_vs_applied.applied_provenance).toEqual([
      "best-practice-applied.md: 1 applied event(s)",
      "insight-applied.md: 2 applied event(s)",
    ]);
    expect(report.created_vs_applied.ratio).toBe(0.375);
  });

  it("family 2 — time-to-distill: 2 candidates, median 3.25 days, max 6 days", () => {
    expect(report.time_to_distill.count).toBe(2);
    expect(report.time_to_distill.median_days).toBe(3.25);
    expect(report.time_to_distill.max_days).toBe(6);
  });

  it("family 3 — backlogs: distill 2 (11 substantive − 9 stamped), queue 2, pending-tag 2 (1 acted, 1 skipped)", () => {
    expect(report.backlogs.distill.latest_substantive).toBe(11);
    expect(report.backlogs.distill.stamped).toBe(9);
    expect(report.backlogs.distill.backlog).toBe(2);
    expect(report.backlogs.distill.series).toEqual([
      { date: "2026-10-01", scanned: 30, substantive: 10, distilled: 8, claims: 6, errors: 0 },
      { date: "2026-10-02", scanned: 32, substantive: 11, distilled: 3, claims: 2, errors: 0 },
    ]);
    expect(report.backlogs.review_queue).toBe(2);
    expect(report.backlogs.pending_tag).toEqual({ backlog: 2, acted: 1, skipped: 1 });
  });

  it("family 4 — refutation: 1 refuted vs 1 corroborated in period → rate 0.5; snapshot 1 of 5", () => {
    expect(report.refutation.refuted).toBe(1);
    expect(report.refutation.corroborated).toBe(1);
    expect(report.refutation.rate).toBe(0.5);
    expect(report.refutation.total_claims).toBe(5);
    expect(report.refutation.refuted_claims).toBe(1);
    expect(report.refutation.snapshot_pct).toBeCloseTo(0.2, 10);
  });

  it("family 5 — schema compliance: drift 1 → 4 across the period's prune passes", () => {
    expect(report.schema_compliance.series).toEqual([
      { date: "2026-10-07", fixes: 2, drift: 1 },
      { date: "2026-10-14", fixes: 0, drift: 4 },
    ]);
    expect(report.schema_compliance.latest_drift).toBe(4);
  });

  it("names the ok receipt that left the writer's pinned shape — never a silent skip; a FAILED pass is a fact, not a finding", () => {
    expect(report.findings.some((f) => f.includes("2026-10-03") && f.includes("distill") && f.includes("crashed mid-pass"))).toBe(true);
    expect(report.findings.some((f) => f.includes("2026-10-04"))).toBe(false);
  });

  it("missing substrates are stated, never faked: queue null → finding; stamped null → backlog null", () => {
    const { claims } = loadRegistryClaims(fixtureRegistry());
    const { receipts } = parsePasses(fixtureJournal());
    const bare = computeHealthReport({
      period: PERIOD,
      receipts,
      claims,
      candidates: [],
      review_queue: null,
      pending_tag: null,
      distill_stamped: null,
    });
    expect(bare.backlogs.review_queue).toBeNull();
    expect(bare.backlogs.pending_tag.backlog).toBeNull();
    expect(bare.backlogs.distill.backlog).toBeNull();
    expect(bare.findings.some((f) => f.includes("review queue"))).toBe(true);
  });
});

// ── the brief render — the dated, provenance-carrying publication ──────────────

describe("renderHealthBrief", () => {
  const brief = renderHealthBrief(fixtureReport(), { generated_at: "2026-10-31T00:00:00.000Z" });

  it("is deterministic: same report + same clock → identical bytes", () => {
    expect(renderHealthBrief(fixtureReport(), { generated_at: "2026-10-31T00:00:00.000Z" })).toBe(brief);
  });

  it("carries the period title, the job provenance header, and the measures-never-acts boundary", () => {
    expect(brief).toContain("# Brain health — 2026-10");
    expect(brief).toContain("brain-health");
    expect(brief).toContain("MEASURES, never acts");
  });

  it("renders the pinned numbers with their provenance", () => {
    expect(brief).toContain("created: **8**");
    expect(brief).toContain("applied: **3**");
    expect(brief).toContain("adoption ratio: **37.5%**");
    expect(brief).toContain("2026-10-01: claims 6");
    expect(brief).toContain("median: **3.25 days**");
    expect(brief).toContain("max: **6 days**");
    expect(brief).toContain("distill backlog: **2**");
    expect(brief).toContain("review queue: **2**");
    expect(brief).toContain("pending-tag: **2**");
    expect(brief).toContain("refutation rate: **50%**");
    expect(brief).toContain("1 of 5");
    expect(brief).toContain("drift findings: **1 → 4**");
    expect(brief).toContain("latest drift: **4**");
  });

  it("carries the job id and the issue in its generated-view header (the registry naming)", () => {
    expect(BRAIN_HEALTH_JOB).toBe("brain-health");
    expect(brief).toContain("amicode #1687");
  });
});
